    process: { kicker:"Ablauf", title:"Von der Idee zum Launch.", intro:"Kurze Schritte, klare Feedback-Momente und kein unnötig komplizierter Prozess.", items:[["01","Besprechen","Wir klären, was die Website tun soll, für wen sie gedacht ist und welcher Stil passt."],["02","Entwerfen","Wir legen Struktur, Typografie, Farben und Interaktionen fest, bevor die Entwicklung beginnt."],["03","Bauen","Die Website wird responsiv entwickelt und auf Desktop, Tablet und Mobilgerät getestet."],["04","Live","Nach dem letzten Feedback verbinden wir deine Domain und veröffentlichen die Produktionsversion."]] },
    after: { kicker:"Nach deiner Anfrage", title:"Was passiert danach?", intro:"Von der Anfrage bis zur Übergabe bleibt jeder Schritt klar.", items:[["01","Wir bauen deine Website","Wir bauen das gewählte Paket, testen die wichtigsten Abläufe und verarbeiten das vereinbarte Feedback."],["02","Google Discovery","Nach dem Launch liefern wir die technische Basis für Search Console, Sitemap und Crawling, damit Google die Website entdecken und mit der Indexierung beginnen kann."],["03","Dein Admin-Dashboard","Wenn ein Admin-Panel oder CMS enthalten ist, erhältst du Zugriff, um Inhalte, Bilder und andere Seitendaten selbst zu verwalten."],["04","Alles gehört dir","Wir übertragen die vereinbarte Domain, Hosting, Website-Dateien, Konten und weiteren Assets. Das Projekt gehört dir."]] },
